def min_blows(n, x, d, h):
    heads = x
    blows = 0
    while heads > 0:
        for i in range(n):
            if heads >= d[i]:
                heads -= d[i]
                heads += h[i]
                blows += 1
                break
        else:
            return -1
    return blows

