def solve(n, m):
    left, right = 0, 2 * 10**18
    while left < right:
        mid = (left + right) // 2
        if mid * (mid + 1) // 2 <= n - m:
            left = mid + 1
        else:
            right = mid
    return min(right, n) + m

n, m = map(int, input().split())
print(solve(n, m))

