def count_extra_tiles(tiles):
    # Check if the hand contains a koutsu or shuntsu
    for tile in tiles:
        if tiles.count(tile) == 3:
            return 0  # Koutsu found, no extra tiles needed

    suits = set(tile[1] for tile in tiles)
    for suit in suits:
        sorted_tiles = sorted(tile for tile in tiles if tile[1] == suit)
        if len(sorted_tiles) >= 3 and sorted_tiles[2] - sorted_tiles[0] == 2:
            return 0  # Shuntsu found, no extra tiles needed

    # If no mentsu found, need to draw one extra tile
    return 1

# Read input
