    h, m = map(int, time.split(':'))
    while True:
        h = str(h).zfill(2)
        m = str(m).zfill(2)
        if h == m[::-1]:
            break
        m += 1
        if m == 60:
            m = 0
            h = str(int(h) + 1)
    return int(h + m) - int(time)

