def fill_matrix(n, k):
    matrix = [[0] * n for _ in range(n)]

    # Place ones on the diagonal
    for i in range(n):
        matrix[i][i] = 1

    # If k is odd, we cannot achieve a symmetric matrix with all ones on the diagonal
    if k % 2 == 1 and n > 1:
        return -1

    k //= 2
    # Place remaining ones symmetrically around the diagonal
    for i in range(n // 2):
        if k > 0:
            matrix[i][n - 1 - i] = 1
            matrix[n - 1 - i][i] = 1
            k -= 1

    # Check if the matrix is lexicographically maximal
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] == 0 and matrix[j][i] == 0:
                if matrix[i][i + 1] > matrix[j][j + 1]:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    break
                elif matrix[i][i + 1] < matrix[j][j + 1]:
                    return -1

    return matrix


# Read input
n, k = map(int, input().split())
result = fill_matrix(n, k)

# Output the matrix or -1
if result == -1:
    print(-1)
else:
    for row in result:
        print(' '.join(map(str, row)))

