n, k = map(int, input().split())

# create a n*n matrix filled with 0s
matrix = [[0 for _ in range(n)] for _ in range(n)]

# try placing k knights on the matrix
for i in range(k):
    row, col = random.randint(0, n-1), random.randint(0, n-1)
    if can_place_knight(matrix, row, col):
        place_knights(matrix, row, col)
        break

# if a solution was found, print the matrix
if knight_tour_exists(matrix):
    for row in matrix:
        print(*row)
else:
    print(-1)

def can_place_knight(matrix, row, col):
    # check if the given cell is valid
    if row < 0 or row >= n or col < 0 or col >= n:
        return False

    # check if the cell is already occupied
    if matrix[row][col]!= 0:
        return False

    # check if placing the knight at the given cell results in a valid tour
    return knight_tour_exists(matrix, row, col, visited=[])

def place_knights(matrix, row, col):
    # mark the current cell as occupied
    matrix[row][col] = 1

    # try placing the other knight
    for i, j in [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]:
        new_row, new_col = row + i, col + j
        if can_place_knight(matrix, new_row, new_col):
            place_knights(matrix, new_row, new_col)
            break

def knight_tour_exists(matrix, row=0, col=0, visited=[]):
    # check if all knight's have been placed
    if len(visited) == n * n:
        return True

    # check if the current cell has been visited before
    for i, j in visited:
        if i == row and j == col:
            return False

    # mark the current cell as visited
    visited.append((row, col))

    # try all possible moves from the current cell
    for i, j in [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]:
        new_row, new_col = row + i, col + j
        if can_place_knight(matrix, new_row, new_col):
            if knight_tour_exists(matrix, new_row, new_col, visited):
                return True

    # if no valid move was found, return False
    return False

