def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def birthday_paradox(n, k):
    total_ways = pow(2, n * k, 10**6 + 3)
    no_same_birthday_ways = 0
    for r in range(1, k + 1):
        ways_with_same_birthday = pow(2, n * r, 10**6 + 3)
        ways_without_same_birthday = total_ways - ways_with_same_birthday
        no_same_birthday_ways += ways_without_same_birthday
        total_ways = total_ways - ways_with_same_birthday
    no_same_birthday_ways %= 10**6 + 3
    return no_same_birthday_ways, pow(lcm(no_same_birthday_ways, total_ways), gcd(no_same_birthday_ways, total_ways), 10**6 + 3)

