def is_palindrome(s):
    return s == s[::-1]

def longest_non_palindrome(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if is_palindrome(s[i:j + 1]):
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]) + 1

    return dp[0][n - 1]

