            result[i] = 0
        else:
            left, right = 0, len(zeros)
            while left < right:
                mid = (left + right) // 2
                if zeros[mid] - i < result[i]:
                    right = mid
                else:
                    left = mid + 1
            result[i] = zeros[left] - i if left < len(zeros) else abs(i)

    return ' '.join(str(d) for d in result)


