def prefix_function(s):
    pi = [0] * len(s)
    for i in range(1, len(s)):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def solve():
    n = int(input())
    s = input()
    m = len(s)
    pi = prefix_function(s)
    dp = [[[0] * (m + 1) for _ in range(m)] for _ in range(n + 1)]
    dp[0][0][0] = 1
    for i in range(n):
        for j in range(m):
            for k in range(m + 1):
                for l in range(2):
                    if dp[i][j][k]:
                        for c in range(2):
                            nj = j
                            while nj > 0 and chr(ord('0') + c) != s[nj]:
                                nj = pi[nj - 1]
                            if chr(ord('0') + c) == s[nj]:
                                nj += 1
                            nk = k
                            if nj == m:
                                nk = max(nk, j + 1, pi[j] + 1)
                                nj = pi[j]
                            dp[i + 1][nj][nk] += dp[i][j][k]
