from math import log2, ceil

def solve(n, k):
    if n == 1 and k == 2:
        return "Yes\n-1 -1"

    if n == 0:
        return "No"

    ans = []
    for i in range(k-1, -1, -1):
        x = ceil(log2(n))
        ans.append(x-1)
        n -= 2**x

    if n != 0:
        return "No"

    ans.sort(reverse=True)
    return "Yes\n" + " ".join(map(str, ans))

