def manhattan_distance(x, y, a, b):
    return abs(x - a) + abs(y - b)

def min_ops_to_reach(seq, x, y):
    dx, dy = x, y
    steps = 0
    for op in seq:
        if op == "U":
            dy += 1
        elif op == "D":
            dy -= 1
        elif op == "L":
            dx -= 1
        elif op == "R":
            dx += 1
        steps += 1
        if dx == x and dy == y:
            break
    return steps if (dx == x and dy == y) else -1

