def solve(n, t, songs):
    songs.sort(key=lambda x: x[0])
    dp = [[[0 for _ in range(4)] for _ in range(t + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 1
    for i in range(1, n + 1):
        for j in range(t + 1):
            for k in range(4):
                dp[i][j][k] = dp[i - 1][j][k]
                if j >= songs[i - 1][0] and k != songs[i - 1][1]:
                    dp[i][j][k] += dp[i - 1][j - songs[i - 1][0]][songs[i - 1][1]]
                dp[i][j][k] %= mod
    return dp[n][t][0]

if __name__ == "__main__":
