from math import factorial

def solve(n, k, S, a):
    dp = [[[0] * (k + 1) for _ in range(S + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 1

    for i in range(1, n + 1):
        for j in range(S + 1):
            for l in range(k + 1):
                dp[i][j][l] = dp[i - 1][j][l]
                if j >= a[i - 1] and l > 0:
                    dp[i][j][l] += dp[i - 1][j - a[i - 1]][l - 1]

    return dp[n][S][k]

