from math import log

def can_achieve(n, k, a):
    v = [0] * n
    for i in range(int(log(max(a), k)) + 1):
        found = False
        for j in range(n):
            if v[j] + k**i == a[j]:
                v[j] += k**i
                found = True
                break
        if not found:
            for j in range(n):
                if v[j] + k**i < a[j]:
                    v[j] += k**i
                    found = True
                    break
        if not found:
            return "NO"
    return "YES"

