def find_pocket(n, m, x, y, vx, vy):
    if vx == 0:
        if vy == 1:
            return f"{x} {m}"
        else:
            return f"{x} 0"
    elif vy == 0:
        if vx == 1:
            return f"{n} {y}"
        else:
            return f"0 {y}"
    else:
        dx = min(x, n-x) / abs(vx)
        dy = min(y, m-y) / abs(vy)
        t = min(dx, dy)
        nx = x + vx * t
        ny = y + vy * t
        if nx == 0:
            return f"0 {ny}"
        elif nx == n:
            return f"{n} {ny}"
        elif ny == 0:
            return f"{nx} 0"
        elif ny == m:
            return f"{nx} {m}"
        else:
            return "-1"

