    res = set()

    factor = factorization(n)

    for p, c in factor:
        if res == set():
            for i in range(c + 1):
                res.add(p ** i)
        else:
            t = set()
            for i in range(1, c + 1):
                for m in res:
                    t.add(m * p**i)
            res = res | t

    res = list(sorted(res))
    return res

