def is_infinite(x, y, vertical_lines, horizontal_lines):
    for a, b, c in vertical_lines:
        if a < x < b and c <= y:
            return True
    for d, e, f in horizontal_lines:
        if e < y < f and d <= x:
            return True
    return False

