def min_cost_alphabet(n, c0, c1):
    # Calculate the cost of representing each letter using k bits
    def cost_of_k_bits(k):
        return (c0 * (1 << (k - 1))) + (c1 * ((1 << k) - (1 << (k - 1))))

    # Check for special cases where n is a power of 2
    if n == (1 << k).bit_length() - 1:
        return cost_of_k_bits(k)

    # Find the smallest k such that 2^k > n
    k = 1
    while (1 << k) <= n:
        k += 1

    # Calculate the cost of using k bits for the first n-1 letters
    # and then using k-1 bits for the last letter
    return cost_of_k_bits(k) + cost_of_k_bits(k - 1) - c1

# Read input
