def solve(n, s):
    # Initialize a dictionary to keep track of the number of stones in the pile after each operation
    stone_count = {0: 0}

    # Iterate through the operations and update the number of stones in the pile
    for i in range(1, n+1):
        if s[i] == "+":
            stone_count[stone_count[stone_count[i-1]]+1] = stone_count[stone_count[i-1]]+1
        else:
            stone_count[stone_count[i-1]] -= 1

    # Return the minimum number of stones in the pile after the operations
    return min(stone_count.values())

