def minCoins(n, x, y):
    # Initialize a dictionary to keep track of the number of coins spent for each substring
    coin_count = {substring: 0 for substring in itertools.combinations(range(n), n)}

    # Loop through the string and apply the operations
    for i in range(n):
        # Reverse a substring
        if i % 2 == 0:
