import sys
from math import sqrt
from collections import defaultdict

MOD = 10**9 + 7
MAX = 10**6 + 5
phi = [0]*MAX
is_prime = [0]*MAX
prime = []
f = [0]*MAX
g = [0]*MAX
F = defaultdict(int)

def sieve():
    phi[1] = 1
    for i in range(2, MAX):
        if not is_prime[i]:
            phi[i] = i - 1
            prime.append(i)
        j = 0
        while j < len(prime) and i * prime[j] < MAX:
            is_prime[i * prime[j]] = 1
            if i % prime[j] == 0:
                phi[i * prime[j]] = phi[i] * prime[j]
                break
            else:
                phi[i * prime[j]] = phi[i] * (prime[j] - 1)
            j += 1

def solve(n, k):
    if k == 1 or n <= 3:
        return f[n]
    if k % 2 == 0 and F[(n, k)]:
        return F[(n, k)]
    if k % 2 == 0:
        F[(n, k)] = solve(solve(n, k - 1), k - 1)
    else:
        F[(n, k)] = solve(solve(n, k - 1), 1)
    return F[(n, k)]

