    def subnet_to_range(subnet):
        if '/' in subnet:
            ip, bits = subnet.split('/')
            mask = (1 << (32 - int(bits))) - 1
            return (int(ip.replace('.', '')) & ~mask, int(ip.replace('.', '')) | mask)
