def is_valid_subnet(subnet):
    if '/' in subnet:
        subnet, mask = subnet.split('/')
        mask = int(mask)
        if mask < 0 or mask > 32:
            return False
        return True
    else:
        return True

def convert_subnet_to_int(subnet):
    if '/' in subnet:
        subnet, mask = subnet.split('/')
        mask = int(mask)
        subnet = subnet.split('.')
        subnet = [int(x) for x in subnet]
        subnet = subnet[:mask]
        subnet = [x << (32 - i - 1) for i, x in enumerate(subnet)]
        subnet = sum(subnet)
        return subnet
    else:
        subnet = subnet.split('.')
        subnet = [int(x) for x in subnet]
        subnet = [x << (32 - i - 1) for i, x in enumerate(subnet)]
        subnet = sum(subnet)
        return subnet

def convert_int_to_subnet(subnet):
    subnet = [subnet >> (32 - i - 1) & 255 for i in range(4)]
    subnet = '.'.join([str(x) for x in subnet])
    return subnet

def merge_subnets(subnets):
    subnets = sorted(subnets)
    merged_subnets = []
    current_subnet = subnets[0]
    for subnet in subnets[1:]:
        if current_subnet[1] == subnet[1]:
            current_subnet = (current_subnet[0], current_subnet[1], max(current_subnet[2], subnet[2]))
        else:
            merged_subnets.append(current_subnet)
            current_subnet = subnet
    merged_subnets.append(current_subnet)
    return merged_subnets

def optimize_blacklist(subnets):
    blacklist = []
    whitelist = []
    for subnet in subnets:
        if subnet[0] == '-':
            blacklist.append(subnet)
        else:
            whitelist.append(subnet)

    blacklist = merge_subnets(blacklist)
    whitelist = merge_subnets(whitelist)

    optimized_blacklist = []
    for subnet in blacklist:
        if any(subnet[1] == x[1] and subnet[2] >= x[2] for x in whitelist):
            continue
        optimized_blacklist.append(subnet)

    return optimized_blacklist

def print_output(optimized_blacklist):
    if len(optimized_blacklist) == 0:
        print(-1)
    else:
        print(len(optimized_blacklist))
