            if subnet[2] == 32:
                print(convert_int_to_subnet(subnet[1]))
            else:
                print(convert_int_to_subnet(subnet[1]) + '/' + str(subnet[2]))

def main():
    subnets = read_input()
    optimized_blacklist = optimize_blacklist(subnets)
    print_output(optimized_blacklist)

if __name__ == "__main__":
