    if s[0] == '0':
        return max(longestAlternatingSubsequence(n-1, s[1:]), longestAlternatingSubsequence(n-1, s[1:]))
    else:
        return max(longestAlternatingSubsequence(n-1, s[1:]), longestAlternatingSubsequence(n-1, s[0:]))

