    factors = prime_factors(n)
    count = {}
    for factor in factors:
        if factor in count:
            count[factor] += 1
        else:
            count[factor] = 1
    return count

def prime_factors_count_max(count):
    max_count = 0
    for factor in count:
        if count[factor] > max_count:
            max_count = count[factor]
    return max_count

def prime_factors_count_min(count):
    min_count = 1000000000
    for factor in count:
        if count[factor] < min_count:
            min_count = count[factor]
    return min_count

def solve(x):
    count = prime_factors_count(x)
    max_count = prime_factors_count_max(count)
    min_count = prime_factors_count_min(count)
    return max_count - min_count

