import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n))+1):
        if n % i == 0:
            return False
    return True

def flip_cards(cards, p):
    start = cards.index(min(cards))
    end = start + p
    cards[start:end] = [1-card for card in cards[start:end]]

N = int(input())
cards = list(map(int, input().split()))

operations = 0
while not all(card == 0 for card in cards):
    p = min(min(cards), int(math.log(N, 2))+1)
    if is_prime(p):
        flip_cards(cards, p)
        operations += 1
    else:
        operations += math.ceil(N/p)
    N -= p
print(operations)

