import sys

def find_shortest_cycle(n, a):
    visited = [False] * n
    parent = [-1] * n
    min_cycle_length = sys.maxsize

    for i in range(n):
        if not visited[i]:
            stack = [(i, -1)]
            visited[i] = True

            while stack:
                node, par = stack.pop()

                for j in range(n):
                    if a[node] & a[j] != 0 and j != par:
                        if visited[j]:
                            cycle_length = len(find_path(node, j, parent)) + 1
                            min_cycle_length = min(min_cycle_length, cycle_length)
                        else:
                            visited[j] = True
                            parent[j] = node
                            stack.append((j, node))

    return -1 if min_cycle_length == sys.maxsize else min_cycle_length

def find_path(start, end, parent):
    path = []
    current = end
    while current != start:
        path.append(current)
            current = parent[current]
    path.append(start)
    return path[::-1]

