import math

def dfs(node, visited, graph):
    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            dfs(neighbor, visited, graph)

def is_special(point, n, graph):
    distances = [math.sqrt(point[0]**2 + point[1]**2) for point in graph]
    if min(distances) <= n:
        return False
    return True

def min_blocked_points(n, graph):
    special_points = [point for point in graph if is_special(point, n, graph)]
    blocked_points = set()
    for point in special_points:
        neighbors = graph[point]
        for neighbor in neighbors:
            if neighbor not in blocked_points:
                blocked_points.add(neighbor)
                dfs(neighbor, {}, graph)
    return len(blocked_points)

