def count_paintings(N, M, X, edges):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w, 1) if u < v else (v, 1, u))
        graph[v].append((u, w, 1) if u > v else (u, 1, v))
    visited = [False] * (N + 1)
    result = [0]
    for i in range(1, N + 1):
        if not visited[i]:
            dfs(graph, visited, i, -1, 0, result)
    return result[0]

