    edges = []
    for _ in range(m):
        u, v, w = map(int, sys.stdin.readline().split())
        edges.append((u, v, w))

    spanning_trees = []
    for edges_subset in itertools.combinations(edges, n-1):
        tree = kruskal(edges_subset, n)
        if sum([e[2] for e in tree]) == x:
            spanning_trees.append(tree)

    if len(spanning_trees) == 0:
        print(0)
        return

    min_tree = min(spanning_trees, key=lambda x: sum([e[2] for e in x]))
    white_black_trees = []
    for tree in spanning_trees:
        white_black_tree = []
        for edge in tree:
            if (edge[0] in (min_tree[0], min_tree[1]) and edge[2] % 2 == 0) or (edge[1] in (min_tree[0], min_tree[1]) and edge[2] % 2 == 1):
                white_black_tree.append(edge)
            else:
                white_black_tree.append((edge[0], edge[1], edge[2] ^ 1))
        white_black_trees.append(white_black_tree)

    print(len(list(filter(lambda x: sum([e[2] for e in x]) == x, white_black_trees))))

