def find_targets(n, hits):
    # Check if the given hits are valid
    for hit in hits:
        if hit > 3:
            return -1

    # Try to construct a valid configuration
    targets = []
    for i in range(n):
        for j in range(1, hit[i] + 1):
            # Place targets in a zigzag pattern
            if j % 2 == 1:
                row = (n - i) - (j // 2)
                if row <= 0:
                    return -1
                targets.append((row, i + 1))
            else:
                row = (n - i) - ((j // 2) - 1)
                if row > n:
                    return -1
                targets.append((row, i + 1))

    # Check if the constructed configuration is valid
    target_counts = [0] * n
    for target in targets:
        r, c = target
        if target_counts[r - 1] >= 2 or target_counts[c - 1] >= 2:
            return -1
        target_counts[r - 1] += 1
        target_counts[c - 1] += 1

    # Output the constructed configuration
    print(len(targets))
    for target in targets:
        print(target[0], target[1])

