def lis(arr):
    n = len(arr)
    lis = [1] * n
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
    return max(lis)


def lds(arr):
    n = len(arr)
    lds = [1] * n
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] < arr[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1
    return max(lds)


def permute(arr, n, a, b):
    if lis(arr) < a or lds(arr) < b:
        return -1
    else:
