def count_ways(N, M, conditions):
    MOD = 10**9 + 7
    dp = [[[0] * 4 for _ in range(4)] for _ in range(N+1)]
    dp[0][0][0] = 1

    for i in range(1, N+1):
        for j in range(4):
            for k in range(4):
                for l, r, x in conditions:
                    if i < r:
                        continue
                    cnt = 0
                    if j + (x == 1) == k:
                        cnt += dp[i-1][j][k]
                    if x == 2 and j == 0 and k == 0:
                        cnt += dp[i-1][0][0]
                    if x == 3 and j != k:
                        cnt += dp[i-1][j][k]
                    dp[i][j][k] = (dp[i][j][k] + cnt) % MOD

    ans = 0
    for j in range(4):
        for k in range(4):
            ans = (ans + dp[N][j][k]) % MOD

    return ans

