def is_correct(s):
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def can_fix(s):
    for i in range(len(s)):
        for j in range(len(s)):
            if i == j:
                continue
            t = s[:i] + s[j] + s[i+1:j] + s[i] + s[j+1:]
            if is_correct(t):
                return True
    return False

