    # Initialize a dictionary to store the weakened common divisors
    wcd = {}

    # Iterate through the pairs and find the weakened common divisors
    for i in range(len(pairs)):
        a, b = pairs[i]
        if a in wcd and b in wcd[a]:
            wcd[a] = max(wcd[a], wcd[b])
        else:
            wcd[a] = 1

    # Return the maximum weakened common divisor found
    return max(wcd.values())

