import sys

def main():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    a.sort()

    if k > n:
        print("NO")
        return

    colors = [0] * n
    for i in range(k):
        for j in range(i, n, k):
            colors[j] = i + 1

    print("YES")
    print(*colors)

